# Try rotation 90 degrees clockwise
def rotate_90(grid):
    n = len(grid)
    return [[grid[n-1-j][i] for j in range(n)] for i in range(n)]

# Also rotation 180 and 270
def rotate_180(grid):
    return rotate_90(rotate_90(grid))

def rotate_270(grid):
    return rotate_90(rotate_180(grid))

input_grid = [
    [1, 6, 6, 6, 6, 7],
